require_once __DIR__.'/../includes/functions.php';require_login();
$stmt=db()->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$stmt->execute([(int)($_GET['id']??0),current_user()['id']]);$order=$stmt->fetch();
